<template>
<div class="app">
  <section v-if="!user" class="login-wrap"><form class="login-card" @submit.prevent="login"><img class="login-logo" src="/indian-navy-project-seabird.png" alt="Indian Navy Project Seabird logo"/><h1>Material Pass Management</h1><p>Sign in to continue</p><label>Username<input v-model="loginForm.username" autocomplete="username" required /></label><label>Password<div class="password-wrap"><input v-model="loginForm.password" :type="showLoginPassword ? 'text' : 'password'" autocomplete="current-password" required /><button type="button" class="eye-button" :aria-label="showLoginPassword ? 'Hide password' : 'Show password'" @click="showLoginPassword=!showLoginPassword">{{showLoginPassword ? '🙈' : '👁️'}}</button></div></label><p v-if="loginError" class="error">{{loginError}}</p><button class="primary" type="submit">Sign In</button></form></section>
  <template v-else>
    <header><div class="brand-block"><img class="brand-logo" src="/indian-navy-project-seabird.png" alt="Indian Navy Project Seabird logo"/><div><h1>Material Pass Management</h1><p>Material entry, arrival and return tracking · Signed in as {{user.username}} ({{user.role}})</p></div></div><div class="head-actions"><button v-if="user.role==='admin'" @click="openUsers">Manage Accounts</button><button @click="logout">Log Out</button><button v-if="user.role==='user'" class="primary" @click="openNew">+ New Material Pass</button></div></header>
    <nav><button :class="{active:dashboardMode}" @click="dashboardMode=true;loadDashboard()">Dashboard</button><button :class="{active:!dashboardMode&&tab===''}" @click="dashboardMode=false;tab='';load()">All Passes</button><button v-for="t in tabs.filter(x=>x.key)" :key="t.key" :class="{active:!dashboardMode&&tab===t.key}" @click="dashboardMode=false;tab=t.key;load()">{{t.label}}</button></nav>
    <main v-if="dashboardMode" class="dashboard-page">
      <section class="dash-heading"><div><span class="eyebrow">OVERVIEW / REPORTING</span><h2>Material Pass Dashboard</h2><p>Daily movement, company-wise material quantities and searchable pass records.</p></div><div class="head-actions"><button @click="exportReport">Download Excel Report</button><button class="primary" @click="loadDashboard">↻ Refresh Dashboard</button></div></section>
      <section class="filter-panel"><div class="filter-title"><div><h3>Find material and pass records</h3><p>Search across pass, company, contract, item and IT asset fields.</p></div><button @click="resetDashboardFilters">Reset filters</button></div><div class="dashboard-filters">
        <label>From date<input type="date" v-model="dashboardFilters.from"/></label><label>To date<input type="date" v-model="dashboardFilters.to"/></label><label v-if="user.role==='admin'">Company / Contractor<input v-model="dashboardFilters.company" placeholder="e.g. XYZ Company"/></label><label v-else>Company / Contractor<input :value="user.company_name || 'Company not assigned'" disabled/></label><label>Material / Asset field<input v-model="dashboardFilters.material" placeholder="Description, serial, brand, tag..."/></label><label>Category<select v-model="dashboardFilters.category"><option value="">All categories</option><option>General</option><option>IT Asset</option></select></label><label>Status<select v-model="dashboardFilters.status"><option value="">All statuses</option><option>Recorded - Pending Arrival</option><option>Pending Arrival Approval</option><option>Arrival Rejected</option><option>Pending Return</option><option>Pending Return Approval</option><option>Return Rejected</option><option>Completed</option></select></label><label>Direction<select v-model="dashboardFilters.direction"><option value="">IN and OUT</option><option value="IN">IN</option><option value="OUT">OUT</option></select></label><label>Search all fields<input v-model="dashboardFilters.search" placeholder="Pass no., model, serial, driver, remarks..." @keyup.enter="loadDashboard"/></label></div><div class="filter-actions"><span>Showing {{dashboardData.passes?.length||0}} matching passes</span><button class="primary" @click="loadDashboard">Search records</button></div></section>
      <div v-if="dashboardLoading" class="empty">Loading dashboard...</div><div v-else-if="dashboardError" class="error dashboard-error">{{dashboardError}} <button @click="loadDashboard">Retry</button></div><template v-else>
      <section class="metric-grid"><article class="metric-card metric-navy"><span>Matching Passes</span><strong>{{dashboardData.summary?.pass_count||0}}</strong><small>Within selected filters</small></article><article class="metric-card"><span>Material Lines</span><strong>{{dashboardData.summary?.item_lines||0}}</strong><small>Individual item rows</small></article><article class="metric-card"><span>Total Quantity</span><strong>{{fmtQty(dashboardData.summary?.pass_qty)}}</strong><small>Quantity requested</small></article><article class="metric-card"><span>Arrived Quantity</span><strong>{{fmtQty(dashboardData.summary?.arrived_qty)}}</strong><small>Recorded at gate</small></article><article class="metric-card"><span>Returned Quantity</span><strong>{{fmtQty(dashboardData.summary?.returned_qty)}}</strong><small>Recorded returns</small></article></section>
      <section class="dash-panel"><div class="panel-heading"><div><h3>Company-wise material quantity</h3><p>Example: XYZ Company — ABC item — 10 Nos</p></div><span class="table-note">Grouped by company + material</span></div><div class="table-scroll"><table class="dash-table"><thead><tr><th>Company / Contractor</th><th>Material / Asset</th><th>Category</th><th>Unit</th><th>Total Qty</th><th>Arrived</th><th>Returned</th><th>Pass Lines</th></tr></thead><tbody><tr v-for="(x,idx) in dashboardData.companyItems" :key="x.company_name+'-'+x.description+'-'+x.uom+'-'+idx"><td><b>{{x.company_name}}</b></td><td>{{x.description}}</td><td><span class="category-pill">{{x.category}}</span></td><td>{{x.uom||'—'}}</td><td><b>{{fmtQty(x.quantity)}}</b></td><td class="qty-arrived">{{fmtQty(x.arrived_qty)}}</td><td class="qty-returned">{{fmtQty(x.returned_qty)}}</td><td>{{x.pass_count}}</td></tr><tr v-if="!dashboardData.companyItems?.length"><td colspan="8" class="empty-cell">No material totals match these filters.</td></tr></tbody></table></div></section>
      <section class="dash-panel"><div class="panel-heading"><div><h3>Daily material pass details</h3><p>Open any pass to review the full material list and IT asset information.</p></div><span class="table-note">Newest first</span></div><div class="table-scroll"><table class="dash-table"><thead><tr><th>Date / Pass No.</th><th>Company / Contractor</th><th>Contract</th><th>Direction / Type</th><th>Materials</th><th>Total Qty</th><th>Status</th><th>Actions</th></tr></thead><tbody><tr v-for="p in dashboardData.passes" :key="p.id"><td><b>{{p.pass_no}}</b><small class="subline">{{fmt(p.created_at)}}</small></td><td>{{p.company_name}}</td><td>{{p.contract_name}}</td><td>{{p.direction==='Entry'?'IN':p.direction==='Exit'?'OUT':p.direction}}<small class="subline">{{p.type}}</small></td><td><span v-for="(i,n) in p.items" :key="i.id"><span v-if="n">, </span>{{i.description}} ({{fmtQty(i.approved_qty)}} {{i.uom}})</span></td><td><b>{{fmtQty(p.items.reduce((sum,i)=>sum+Number(i.approved_qty||0),0))}}</b></td><td><span :class="['badge',returnStatusClass(p)]">{{p.status}}</span></td><td><div class="actions"><button @click="view(p.id)">View</button><button v-if="user.role==='approver'&&['Pending Arrival Approval','Pending Return Approval'].includes(p.status)" @click="openApproval(p.id)">{{p.status==='Pending Arrival Approval'?'Approve Arrival':'Approve Return'}}</button><button v-if="user.role==='approver'&&['Pending Arrival Approval','Pending Return Approval'].includes(p.status)" @click="openReject(p.id)">Reject</button><a :href="`/api/passes/${p.id}/pdf?stage=workflow`" target="_blank">PDF</a></div></td></tr><tr v-if="!dashboardData.passes?.length"><td colspan="8" class="empty-cell">No passes found for the selected filters.</td></tr></tbody></table></div></section>
      <section class="dash-panel"><div class="panel-heading"><div><h3>Most recorded materials</h3><p>Quantity totals across the matching passes.</p></div></div><div class="popular-list"><div v-for="m in dashboardData.materialTotals.slice(0,8)" :key="m.description+'-'+m.uom" class="popular-row"><div><b>{{m.description}}</b><small>{{m.company_count}} companies · {{m.pass_count}} item lines</small></div><strong>{{fmtQty(m.quantity)}} <small>{{m.uom}}</small></strong></div><p v-if="!dashboardData.materialTotals?.length" class="empty-cell">No material totals available.</p></div></section>
      </template>
    </main>
    <main v-else><section class="toolbar"><input v-model="search" @keyup.enter="load" placeholder="Search pass, company or contract..."/><button @click="load">Search</button></section>
      <div class="list-toolbar"><span>{{tab || 'All Passes'}} · {{passes.length}} records</span><button @click="exportTab">Download Excel</button></div>
      <div v-if="loading" class="empty">Loading...</div><div v-else-if="!passes.length" class="empty">No material passes found.</div>
      <div v-else class="table-scroll pass-list-scroll"><table class="dash-table pass-list-table"><thead><tr><th>Pass No.</th><th>Date</th><th>Company / Contractor</th><th>Contract</th><th>Direction</th><th>Type</th><th>Quantity</th><th>Pending Qty</th><th>Status</th><th>Actions</th></tr></thead><tbody><tr v-for="p in passes" :key="p.id"><td><b>{{p.pass_no}}</b></td><td>{{fmt(p.created_at)}}</td><td>{{p.company_name}}</td><td>{{p.contract_name}}</td><td>{{p.direction==='Entry'?'IN':p.direction==='Exit'?'OUT':p.direction}}</td><td>{{p.type}}</td><td>{{fmtQty((p.items||[]).reduce((n,i)=>n+Number(i.approved_qty||0),0))}}</td><td>{{fmtQty(p.pending_count)}}</td><td><span :class="['badge',returnStatusClass(p)]">{{p.status}}</span></td><td><div class="actions"><button @click="view(p.id)">View</button><button v-if="user.role==='user'&&canEditPass(p)" @click="editPass(p.id)">Edit</button><button v-if="user.role==='user'&&['Recorded - Pending Arrival','Arrival Rejected'].includes(p.status)" @click="arrival(p.id)">Record Arrival</button><button v-if="user.role==='user'&&p.status==='Pending Arrival Approval'" @click="editArrival(p.id)">Edit Arrival</button><button v-if="user.role==='user'&&['Pending Return','Return Rejected'].includes(p.status)" @click="returnItems(p.id)">Record Return</button><button v-if="user.role==='approver'&&['Pending Arrival Approval','Pending Return Approval'].includes(p.status)" @click="openApproval(p.id)">{{p.status==='Pending Arrival Approval'?'Approve Arrival':'Approve Return'}}</button><button v-if="user.role==='approver'&&['Pending Arrival Approval','Pending Return Approval'].includes(p.status)" @click="openReject(p.id)">Reject</button><a :href="`/api/passes/${p.id}/pdf?stage=workflow`" target="_blank">PDF</a></div></td></tr></tbody></table></div>
    </main>
    <div v-if="showForm" class="modal"><div class="dialog large"><div class="dialoghead"><h2>{{editingPassId ? 'Edit Material Pass' : 'New Material Pass'}}</h2><button @click="showForm=false">×</button></div><form @submit.prevent="create"><div class="grid">
      <label>Contract Name*<input v-model="form.contract_name" :readonly="user.role==='user'" required/></label><label>Company Name*<input v-model="form.company_name" :readonly="user.role==='user'" :placeholder="user.role==='user' ? 'Assigned company' : 'Enter company name'" required/></label><label>Direction*<select v-model="form.direction" required><option value="IN">IN</option><option value="OUT">OUT</option></select></label><label>Type*<select v-model="form.type" required><option>Returnable</option><option>Non-Returnable</option></select></label><label v-if="form.type==='Returnable'">Date of Return*<input type="date" v-model="form.return_date" required/></label><label>Mode*<select v-model="form.mode" required><option>By Hand</option><option>By Vehicle</option></select></label><label>Issued By*<input v-model="form.issued_by" required/></label><label>Destination<input v-model="form.destination"/></label><label v-if="form.type==='Non-Returnable'&&form.direction==='OUT'">Officer Authority / Authorisation Reference*<input v-model="form.officer_authority" required placeholder="Officer name, rank or authority reference"/></label>
      </div><h3>Material Details</h3><div class="itemtable"><div class="tr th"><span>#</span><span>Category / Description</span><span>Unit</span><span>Qty</span><span>Remarks</span><span></span></div><div v-for="(i,n) in form.items" :key="n" class="item-block"><div class="tr"><span>{{n+1}}</span><div><select v-model="i.category"><option>General</option><option>IT Asset</option></select><input v-model="i.description" placeholder="Material description *" required/></div><input v-model="i.uom" required placeholder="Nos"/><input v-model.number="i.approved_qty" min="1" type="number" required/><input v-model="i.remarks" placeholder="Remarks"/><button type="button" @click="removeItem(n)">×</button></div><div v-if="i.category==='IT Asset'" class="asset-fields"><b>IT Asset Details — Item {{n+1}}</b><div class="grid"><label>Asset Type<input v-model="i.asset_type" placeholder="Laptop / Desktop / Printer"/></label><label>Brand<input v-model="i.asset_brand" placeholder="Dell / HP / Lenovo"/></label><label>Model<input v-model="i.asset_model"/></label><label>Serial Number<input v-model="i.asset_serial"/></label><label>Asset Tag / Inventory No.<input v-model="i.asset_tag"/></label><label>Condition<select v-model="i.asset_condition"><option value="">Select condition</option><option>New</option><option>Good</option><option>Repair</option><option>Damaged</option></select></label><label>Assigned To / Custodian<input v-model="i.asset_owner"/></label><label>Purpose / Remarks<input v-model="i.asset_purpose"/></label></div></div></div></div><button type="button" @click="addItem">+ Add Item</button><div class="footer"><button type="button" @click="showForm=false">Cancel</button><button class="primary" type="submit">Submit & Generate Pass</button></div></form></div></div>
    <div v-if="selected" class="modal"><div class="dialog large"><div class="dialoghead"><h2>{{selected.pass_no}}</h2><button @click="selected=null">×</button></div><div class="details"><p><b>Status:</b> {{selected.status}}</p><p v-if="selected.rejection_remark"><b>Rejected By:</b> {{selected.rejected_by||'—'}} · <b>Rejected At:</b> {{fmt(selected.rejected_at)}}</p><p v-if="selected.rejection_remark"><b>Rejection Remark:</b> {{selected.rejection_remark}}</p><p><b>Company:</b> {{selected.company_name}} · <b>Contract:</b> {{selected.contract_name}}</p><p><b>Direction:</b> {{selected.direction==='Entry'?'IN':selected.direction==='Exit'?'OUT':selected.direction}} · <b>Type:</b> {{selected.type}} · <b>Issued By:</b> {{selected.issued_by}}</p><p><b>Transport:</b> {{selected.mode}} · <b>Escort:</b> {{selected.escort_name||'-'}} · <b>Destination:</b> {{selected.destination||'-'}}</p><div class="table-scroll"><table><thead><tr><th>#</th><th>Category</th><th>Description / IT asset details</th><th>Unit</th><th>Quantity</th><th v-if="selected.arrival_transactions?.length" >Arrived</th><th v-if="selected.return_transactions?.length">Returned</th><th v-if="selected.return_transactions?.length">Pending Quantity</th><th>Status</th></tr></thead><tbody><tr v-for="i in selected.items" :key="i.id"><td>{{i.sl_no}}</td><td>{{i.category}}</td><td>{{i.description}}<small v-if="i.category==='IT Asset'" class="asset-line">{{[i.asset_type,i.asset_brand,i.asset_model,i.asset_serial,i.asset_tag,i.asset_condition,i.asset_owner,i.asset_purpose].filter(Boolean).join(' · ')}}</small></td><td>{{i.uom}}</td><td>{{i.approved_qty}}</td><td v-if="selected.arrival_transactions?.length" class="qty-arrived">{{i.arrived_qty}}</td><td v-if="selected.return_transactions?.length" class="qty-returned">{{i.returned_qty}}</td><td v-if="selected.return_transactions?.length">{{Math.max(0,Number(i.arrived_qty||0)-Number(i.returned_qty||0))}}</td><td>{{i.item_status}}</td></tr></tbody></table></div><section v-if="selected.return_transactions?.length" class="history-block"><h3>Return Transaction History</h3><div class="table-scroll"><table><thead><tr><th>Transaction Date / Time</th><th>Quantity</th><th>Pending Quantity</th><th>Submitted By</th><th>Status</th><th>Approved By</th><th>Approved At</th></tr></thead><tbody><template v-for="tx in selected.return_transactions" :key="tx.id"><tr v-for="item in tx.items" :key="tx.id+'-'+item.id"><td>{{fmt(tx.transaction_at)}}</td><td>{{item.quantity_returned}}</td><td>{{item.pending_quantity_after}}</td><td>{{tx.submitted_by}}</td><td>{{tx.status}}</td><td>{{tx.approved_by||'—'}}</td><td>{{fmt(tx.approved_at)}}</td></tr></template></tbody></table></div></section></div><div class="footer"><button v-if="user.role==='user'&&canEditPass(selected)" @click="editPass(selected.id)">Edit Pass</button><a class="primary linkbtn" :href="`/api/passes/${selected.id}/pdf?stage=${selectedPdfStage}`" target="_blank">Open PDF / QR</a></div></div></div>
    <div v-if="operation" class="modal"><div class="dialog large"><div class="dialoghead"><h2>{{operation==='return'?'Record Return':operation==='arrival-edit'?'Edit Arrival':'Record Arrival'}} · {{operationPass?.pass_no}}</h2><button @click="closeOperation">×</button></div><p v-if="operation!=='return'">Enter arrival details. Quantities default to the original pass quantity and cannot exceed it.</p><p v-else>Enter the quantity returned in this transaction. Quantities default to the remaining balance.</p><div class="grid arrival-details"><label>Escort Name<span class="required">*</span><input v-model="operationDetails.escort_name" :required="operationPass?.mode?.toLowerCase().includes('hand')"/></label><template v-if="!operationPass?.mode?.toLowerCase().includes('hand')"><label>Driver Name<input v-model="operationDetails.driver_name"/></label><label>Driver ID<input v-model="operationDetails.driver_id"/></label><label>Vehicle No.<input v-model="operationDetails.vehicle_no"/></label><label>Vehicle Pass No.<input v-model="operationDetails.vehicle_pass_no"/></label></template></div><div v-for="i in opItems" :key="i.id" class="oprow"><span><b>{{i.description}}</b><small class="subline">{{operation!=='return'?'Original quantity: '+i.approved_qty:'Arrived: '+i.arrived_qty+' · Already returned: '+i.returned_qty+' · Pending: '+i.maxValue}}</small></span><input type="number" min="0" :max="i.maxValue" step="any" v-model.number="i.value" @input="clampQuantity(i)"/></div><div class="footer"><button @click="closeOperation">Cancel</button><button class="primary" @click="saveOperation">Submit for Approval</button></div></div></div>
    <div v-if="showApproval" class="modal"><div class="dialog"><div class="dialoghead"><h2>{{approvalPass?.status==='Pending Return Approval'?'Approve Return':'Approve Arrival'}} · {{approvalPass?.pass_no}}</h2><button @click="showApproval=false">×</button></div><p>Approve the submitted arrival or return record. Your approver name and decision time will be recorded.</p><div class="footer"><button @click="showApproval=false">Cancel</button><button class="primary" @click="confirmApproval">Approve Record</button></div></div></div>
    <div v-if="showReject" class="modal"><div class="dialog"><div class="dialoghead"><h2>Reject {{rejectPass?.pass_no}}</h2><button @click="showReject=false">×</button></div><p>Please provide a clear reason for rejecting this material pass. The remark will be saved with the pass record and included in reports.</p><label>Rejection Remark<textarea v-model="rejectRemark" rows="4" required minlength="3" placeholder="Enter reason for rejection..."></textarea></label><p v-if="rejectError" class="error">{{rejectError}}</p><div class="footer"><button @click="showReject=false">Cancel</button><button class="danger" :disabled="rejectRemark.trim().length<3" @click="confirmReject">Reject Pass</button></div></div></div>
    <div v-if="showUsers" class="modal"><div class="dialog"><div class="dialoghead"><h2>Manage Accounts</h2><button @click="showUsers=false">×</button></div><p>Create Admin, User or Approver accounts. Password must be at least 8 characters.</p><form @submit.prevent="createUser" class="user-form"><label>Username<input v-model="userForm.username" minlength="3" autocomplete="off" required/></label><label>Temporary Password<div class="password-wrap"><input v-model="userForm.password" :type="showCreatePassword ? 'text' : 'password'" minlength="8" autocomplete="new-password" required/><button type="button" class="eye-button" @click="showCreatePassword=!showCreatePassword">{{showCreatePassword ? '🙈' : '👁️'}}</button></div></label><label>Role<select v-model="userForm.role"><option value="user">User</option><option value="approver">Approver</option><option value="admin">Admin</option></select></label><label v-if="userForm.role==='user'">Company Name*<input v-model="userForm.company_name" placeholder="e.g. XYZ Company" required/></label><label v-if="userForm.role==='user'">Contract Name*<input v-model="userForm.contract_name" placeholder="e.g. Seabird Project" required/></label><label v-if="userForm.role==='approver'">Approver Name*<input v-model="userForm.approver_name" placeholder="RPO / LPM full name" required/></label><button class="primary" type="submit">Create Account</button></form><p v-if="userMessage">{{userMessage}}</p><h3>Existing Accounts</h3><div v-if="!users.length">No accounts loaded.</div><div v-for="u in users" :key="u.id" class="user-row"><span><b>{{u.username}}</b> · {{u.role}}<small class="subline">{{u.role==='user' ? 'Company: '+(u.company_name||'Not assigned')+' · Contract: '+(u.contract_name||'Not assigned') : u.role==='approver' ? 'Approver: '+(u.approver_name||'Not assigned') : 'All companies'}}</small></span><div class="actions"><button @click="resetUserPassword(u)">Change Password</button><button v-if="u.role==='user'" @click="setUserCompany(u)">Set Company</button><button v-if="u.id!==user.id" @click="deleteUser(u)">Delete</button><small v-else>Current account</small></div></div></div></div>
  </template>
</div></template>
<script setup>
import {ref,reactive} from 'vue'
const tabs=[{key:'',label:'All Passes'},{key:'Recorded - Pending Arrival',label:'Pending Arrival Record'},{key:'Pending Arrival Approval',label:'Pending Arrival Approval'},{key:'Pending Return',label:'Pending Return'},{key:'Pending Return Approval',label:'Pending Return Approval'},{key:'Completed',label:'Completed / Archive'}]
const user=ref(null),loginForm=reactive({username:'',password:''}),loginError=ref(''),showLoginPassword=ref(false),showCreatePassword=ref(false),userMessage=ref(''),users=ref([]),showUsers=ref(false),userForm=reactive({username:'',password:'',role:'user',company_name:'',contract_name:'',approver_name:''});const showReject=ref(false),rejectPass=ref(null),rejectRemark=ref(''),rejectError=ref('');const showApproval=ref(false),approvalPass=ref(null)
const todayLocal=()=>{const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}
const dashboardMode=ref(true),dashboardLoading=ref(false),dashboardError=ref(''),dashboardData=ref({summary:{},passes:[],companyItems:[],materialTotals:[]})
const dashboardFilters=reactive({from:'',to:'',company:'',material:'',category:'',status:'',direction:'',search:''})
const selectedPdfStage=ref('workflow');const tab=ref(''),search=ref(''),passes=ref([]),loading=ref(false),showForm=ref(false),selected=ref(null),operation=ref(null),opItems=ref([]),operationPass=ref(null),editingPassId=ref(null),operationDetails=reactive({escort_name:'',driver_name:'',driver_id:'',vehicle_no:'',vehicle_pass_no:''})
const newItem=()=>({description:'',uom:'Nos',approved_qty:1,remarks:'',category:'General',asset_type:'',asset_brand:'',asset_model:'',asset_serial:'',asset_tag:'',asset_condition:'',asset_owner:'',asset_purpose:''})
const blank=()=>({contract_name:'',company_name:'',direction:'IN',type:'Non-Returnable',return_date:'',officer_authority:'',mode:'By Hand',escort_name:'',driver_name:'',driver_id:'',vehicle_no:'',vehicle_pass_no:'',issued_by:'',destination:'',items:[newItem()]})
const form=reactive(blank())
async function login(){loginError.value='';const r=await fetch('/api/auth/login',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({username:loginForm.username.trim(),password:loginForm.password})});const d=await r.json();if(!r.ok){loginError.value=d.error||'Login failed';return}user.value=d.user;if(user.value.role==='user'){form.company_name=user.value.company_name||'';form.contract_name=user.value.contract_name||'';}dashboardMode.value=true;await load()}
async function checkSession(){const d=await fetch('/api/auth/me').then(r=>r.json());user.value=d.user;if(user.value){if(user.value.role==='user'){form.company_name=user.value.company_name||'';form.contract_name=user.value.contract_name||'';}load()}} async function logout(){await fetch('/api/auth/logout',{method:'POST'});user.value=null;passes.value=[]}
function reset(){Object.assign(form,blank())}function openNew(){editingPassId.value=null;reset();if(user.value?.role==='user'){form.company_name=user.value?.company_name||'';form.contract_name=user.value?.contract_name||'';}showForm.value=true}
function canEditPass(p){return !!p&&user.value?.role==='user'&&p.status==='Recorded - Pending Arrival'}
async function editPass(id){const r=await fetch('/api/passes/'+id);const p=await r.json();if(!r.ok)return alert(p.error||'Could not load pass');if(!canEditPass(p))return alert('This pass can no longer be edited.');editingPassId.value=id;Object.assign(form,{contract_name:p.contract_name,company_name:p.company_name,direction:p.direction==='Entry'?'IN':p.direction==='Exit'?'OUT':p.direction,type:p.type,return_date:p.return_date||'',officer_authority:p.officer_authority||'',mode:p.mode,escort_name:p.escort_name||'',driver_name:p.driver_name||'',driver_id:p.driver_id||'',vehicle_no:p.vehicle_no||'',vehicle_pass_no:p.vehicle_pass_no||'',issued_by:p.issued_by||'',destination:p.destination||'',items:p.items.map(i=>({...i}))});selected.value=null;showForm.value=true}function addItem(){form.items.push(newItem())}function removeItem(n){if(form.items.length>1)form.items.splice(n,1)}
async function loadDashboard(){if(!user.value)return;dashboardLoading.value=true;dashboardError.value='';try{const q=new URLSearchParams();for(const [k,v] of Object.entries(dashboardFilters))if(v)q.set(k,v);const r=await fetch('/api/dashboard?'+q);if(r.status===401){user.value=null;return}const d=await r.json().catch(()=>({error:'The server returned an invalid response.'}));if(!r.ok)throw new Error(d.error||`Dashboard request failed (${r.status}).`);dashboardData.value={summary:d.summary||{},passes:d.passes||[],companyItems:d.companyItems||[],materialTotals:d.materialTotals||[]}}catch(e){dashboardError.value=`Could not load dashboard data: ${e.message||'Unknown error'}. Check that the server is running and the correct database is in use.`}finally{dashboardLoading.value=false}}
function resetDashboardFilters(){Object.assign(dashboardFilters,{from:'',to:'',company:'',material:'',category:'',status:'',direction:'',search:''});loadDashboard()}
async function load(){if(!user.value)return;if(dashboardMode.value){await loadDashboard();return}loading.value=true;try{const q=new URLSearchParams();if(tab.value)q.set('status',tab.value);if(search.value)q.set('search',search.value);const r=await fetch('/api/passes?'+q);if(r.status===401){user.value=null;return}passes.value=await r.json()}finally{loading.value=false}}
async function create(){const isNewPass=!editingPassId.value;const url=editingPassId.value?'/api/passes/'+editingPassId.value:'/api/passes';const r=await fetch(url,{method:editingPassId.value?'PUT':'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(form)});const d=await r.json();if(!r.ok)return alert(d.error||'Could not save pass');showForm.value=false;editingPassId.value=null;await load();await loadDashboard();await view(d.id,isNewPass?'creation':'workflow')}
async function openApproval(id){approvalPass.value=await fetch('/api/passes/'+id).then(r=>r.json());showApproval.value=true}
async function confirmApproval(){const r=await fetch('/api/passes/'+approvalPass.value.id+'/approve',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({})});const d=await r.json();if(!r.ok){alert(d.error||'Could not approve pass');return}showApproval.value=false;await load();await loadDashboard()}

async function openReject(id){rejectPass.value=await fetch('/api/passes/'+id).then(r=>r.json());rejectRemark.value='';rejectError.value='';showReject.value=true}
async function confirmReject(){rejectError.value='';const r=await fetch('/api/passes/'+rejectPass.value.id+'/reject',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({remark:rejectRemark.value})});const d=await r.json();if(!r.ok){rejectError.value=d.error||'Could not reject pass';return}showReject.value=false;await load()}
function exportReport(){const q=new URLSearchParams();for(const [k,v] of Object.entries(dashboardFilters))if(v)q.set(k,v);window.location.href='/api/reports/material-passes.xls?'+q.toString()}
async function view(id,stage='workflow'){const r=await fetch('/api/passes/'+id);selected.value=await r.json();selectedPdfStage.value=stage}
async function arrival(id){const p=await fetch('/api/passes/'+id).then(r=>r.json());operationPass.value=p;selected.value=null;operation.value='arrival';Object.assign(operationDetails,{escort_name:'',driver_name:'',driver_id:'',vehicle_no:'',vehicle_pass_no:''});opItems.value=p.items.map(i=>({...i,value:Number(i.approved_qty||0),maxValue:Number(i.approved_qty||0)}))}
async function editArrival(id){const p=await fetch('/api/passes/'+id).then(r=>r.json());if(!p||p.status!=='Pending Arrival Approval')return alert('Only an arrival awaiting approval can be edited.');operationPass.value=p;selected.value=null;operation.value='arrival-edit';Object.assign(operationDetails,{escort_name:p.escort_name||'',driver_name:p.driver_name||'',driver_id:p.driver_id||'',vehicle_no:p.vehicle_no||'',vehicle_pass_no:p.vehicle_pass_no||''});opItems.value=p.items.map(i=>({...i,value:Number(i.arrived_qty||0),maxValue:Number(i.approved_qty||0)}))}
async function returnItems(id){const p=await fetch('/api/passes/'+id).then(r=>r.json());operationPass.value=p;selected.value=null;operation.value='return';Object.assign(operationDetails,{escort_name:'',driver_name:'',driver_id:'',vehicle_no:'',vehicle_pass_no:''});opItems.value=p.items.filter(i=>Number(i.arrived_qty||0)>Number(i.returned_qty||0)).map(i=>({...i,value:Math.max(0,Number(i.arrived_qty||0)-Number(i.returned_qty||0)),maxValue:Math.max(0,Number(i.arrived_qty||0)-Number(i.returned_qty||0))}))}
function clampQuantity(i){const n=Number(i.value||0);if(n<0)i.value=0;else if(n>Number(i.maxValue||0))i.value=Number(i.maxValue||0)}
function closeOperation(){operation.value=null;operationPass.value=null;opItems.value=[]}
async function saveOperation(){if(!operationPass.value)return;if(String(operationPass.value.mode||'').toLowerCase().includes('hand')&&!String(operationDetails.escort_name||'').trim())return alert('Escort Name is required for By Hand mode.');for(const i of opItems.value){if(!Number.isFinite(Number(i.value))||Number(i.value)<0||Number(i.value)>Number(i.maxValue))return alert(`Quantity for ${i.description} must be between 0 and ${i.maxValue}.`)}const isArrival=operation.value!=='return';const url='/api/passes/'+operationPass.value.id+'/'+(isArrival?'arrival':'return');const body={items:opItems.value.map(i=>isArrival?{id:i.id,arrived_qty:i.value}:{id:i.id,returned_qty:Number(i.returned_qty||0)+Number(i.value||0)}),...operationDetails};const r=await fetch(url,{method:operation.value==='arrival-edit'?'PUT':'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});const d=await r.json();if(!r.ok)return alert(d.error||'Could not save');const id=operationPass.value.id;closeOperation();await load();await loadDashboard();await view(id)}
function exportTab(){const q=new URLSearchParams();if(tab.value)q.set('status',tab.value);if(search.value)q.set('search',search.value);window.location.href='/api/reports/material-passes.xls?'+q.toString()}
async function openUsers(){showUsers.value=true;userMessage.value='';await loadUsers()}async function loadUsers(){const r=await fetch('/api/users');if(r.ok)users.value=await r.json()}
async function createUser(){userMessage.value='';const r=await fetch('/api/users',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(userForm)});const d=await r.json();if(!r.ok){userMessage.value=d.error;return}userMessage.value='Account created.';userForm.username='';userForm.password='';userForm.role='user';userForm.company_name='';userForm.contract_name='';userForm.approver_name='';showCreatePassword.value=false;await loadUsers()}
async function resetUserPassword(u){const password=prompt(`Enter a new password for ${u.username} (minimum 8 characters):`);if(password===null)return;if(password.length<8){userMessage.value='Password must be at least 8 characters.';return}const r=await fetch('/api/users/'+u.id+'/password',{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({password})});const d=await r.json();userMessage.value=r.ok?'Password updated for '+u.username+'.':(d.error||'Could not update password.')}
async function setUserCompany(u){const company=prompt(`Enter the exact company name for ${u.username}:`,u.company_name||'');if(company===null)return;const contract=prompt(`Enter the exact contract name for ${u.username}:`,u.contract_name||'');if(contract===null)return;const r=await fetch('/api/users/'+u.id+'/company',{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({company_name:company,contract_name:contract})});const d=await r.json();if(!r.ok){userMessage.value=d.error||'Could not update company';return}userMessage.value='Company assignment updated. The user must sign in again to refresh their access.';await loadUsers()}
async function deleteUser(u){if(!confirm(`Delete account ${u.username}?`))return;const r=await fetch('/api/users/'+u.id,{method:'DELETE'});const d=await r.json();if(!r.ok){userMessage.value=d.error;return}await loadUsers()}
function fmt(v){return v?new Intl.DateTimeFormat('en-IN',{timeZone:'Asia/Kolkata',day:'2-digit',month:'2-digit',year:'numeric',hour:'2-digit',minute:'2-digit',second:'2-digit',hour12:true}).format(new Date(v))+' IST':'—'}function fmtQty(v){return Number(v||0).toLocaleString(undefined,{maximumFractionDigits:2})}function badgeClass(s){return s.includes('Rejected')?'danger':s.includes('Pending')?'warn':s==='Completed'?'ok':'blue'}function returnStatusClass(p){if(p.type!=='Returnable')return badgeClass(p.status);const remaining=(p.items||[]).reduce((n,i)=>n+Math.max(0,Number(i.arrived_qty||0)-Number(i.returned_qty||0)),0);if(p.status==='Completed'||(remaining===0&&['Completed','Pending Return Approval'].includes(p.status)))return 'ok';if(remaining>0&&p.return_date&&p.return_date<todayLocal())return 'danger';if(remaining>0)return 'warn';return badgeClass(p.status)}
checkSession()
</script>
